import{_ as a,o as e,c as n,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"The GEST-Engine: From Event Graphs to Synthetic Video. A Full Technical Report","description":"","frontmatter":{"title":"The GEST-Engine: From Event Graphs to Synthetic Video. A Full Technical Report","arxiv":"2607.12231","date":"2026-07-14","authors":"Nicolae Cudlenco, Mihai Masala, Marius Leordeanu","categories":"cs.CV","topics":"智能体视频生成, 显式世界模型, 合成数据","outline":[2,2]},"headers":[],"relativePath":"papers/2607.12231.md","filePath":"papers/2607.12231.md","lastUpdated":null}'),r={name:"papers/2607.12231.md"};function p(l,s,i,o,c,m){return e(),n("div",null,[...s[0]||(s[0]=[t('<h1 id="the-gest-engine-from-event-graphs-to-synthetic-video-a-full-technical-report" tabindex="-1">The GEST-Engine: From Event Graphs to Synthetic Video. A Full Technical Report <a class="header-anchor" href="#the-gest-engine-from-event-graphs-to-synthetic-video-a-full-technical-report" aria-label="Permalink to &quot;The GEST-Engine: From Event Graphs to Synthetic Video. A Full Technical Report&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2607.12231" target="_blank" rel="noreferrer">2607.12231</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-07-14</td></tr><tr><td><strong>作者</strong></td><td>Nicolae Cudlenco, Mihai Masala, Marius Leordeanu</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把时空事件图当作可执行规格，在 GTA:San Andreas 里确定性地演出多角色故事，一次仿真同时吐出 RGB、深度、分割、骨骼、空间关系图与事件-帧对齐，标注边际成本为零。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/agentic">智能体视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频生成模型能产出漂亮画面，却答不出「第 137 帧里 Alice 手上拿的是哪个物体、它在第 20 帧是否存在」。GEST-Engine 走相反方向：<strong>先有语义规格，再有像素</strong>。系统维护一份完整可检查的世界状态——有哪些角色、在哪、在做什么、拿着什么、事件在时空上如何关联——形式化为 Graph of Events in Space and Time（GEST），再在游戏引擎里确定性执行。价值在于三件事成了<strong>构造性保证</strong>而非统计性期望：物体恒存、多角色协同、时序一致，而这正是 Sora、VEO 3 一类隐式世界模型公认的软肋。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>作者把自己定位在<strong>显式世界模型</strong>一侧，与 latent dynamics、DreamerV3、Genie、Sora 这类把状态编码成学得隐向量的路线对立，同时明确两者互补：显式模型生产隐式模型所需的数据。</p><p>合成平台一侧逐条给出缺口：CARLA 传感器丰富但不建模执行叙事活动的人类角色；BEDLAM 用 Unreal 生成照片级人体运动与完美姿态标注、已证明纯合成数据能在真实姿态 benchmark 达到 SOTA（重要的 sim-to-real 先例），但每段序列只有单一活动、无角色间协同；AI2-THOR 单 agent 且面向导航与操作。最接近的 VirtualHome 执行家务程序并给出物体状态变化与动作级标注，但其程序是<strong>单角色顺序脚本</strong>，无跨角色时序编排，环境封闭室内，也不产出逐帧成对空间关系图与事件-帧映射。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>起点是一个朴素观察：若能程序化控制 3D 世界里每个实体，则「谁在何时对什么做了什么」在构造时已知，标注不需事后推断。之后每一步都被具体失败逼出：硬编码 episode 无法扩展催生 World Editor，随机漫游数据不可控促使 2021 年把图的方向从「输出」反转为「输入」，多角色并发时顺序执行不够用于是引入 Allen 区间代数与 Floyd–Warshall 求解。这是<strong>一名研究者六年、约 10 万行代码</strong>的工作，作者对比 VirtualHome 由 7 人团队在相近跨度完成，认为站在既有游戏之上而非从零造世界是让这件事可行的关键决策。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>把视频生成从「学一个文本到像素的映射」改成「把一份可执行的语义规格编译到像素」。因为规格先于像素存在，物体恒存、多角色时序、空间关系就不是需要学出来的性质，而是执行器的不变量。代价是画面被 2004 年的引擎锁死，收益是每帧每个实体都有 ground truth。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以「Alice 和 Bob 同时上床睡觉、Alice 先起床」为例。输入是扁平 JSON，每个事件有 <code>Action</code>、<code>Entities</code>、<code>Location</code>、<code>Properties</code>，顶层 <code>temporal</code> 段记录每角色起始事件、链式 <code>next</code> 指针与命名时序约束。</p><p><strong>Stage 1</strong> 抽出所需角色/地点/物体/动作四张需求表，用带回溯的贪心 set-cover 选出覆盖全部需求的 episode 集合，用双向动作链校验确认某张床真支持完整的 <code>GetOn→Sleep→GetOff</code>，用 Union-Find 找物理连通的 episode 组并聚合成 MetaEpisode。<strong>Stage 2</strong> 做实体接地，核心是 <strong>chain-ID</strong>：教室里 12 张课桌都满足同一序列，每张桌子产生一条独立链并获唯一 ID，它保证同一角色后续动作绑定同一批物理对象，又允许运行时延迟选择——这就是同一份 GEST 每次执行都产出视觉不同视频的原因。<strong>Stage 3</strong> 做时序编排（见 §6）。<strong>Stage 4</strong> 执行 55 个动作类，<code>Move</code> 用 A* 在 World Editor 定义的寻路图上找路，跨场景移动走「暂停-淡出-传送-换内饰-恢复-淡入」五阶段。</p><p>采集侧在一次仿真中通过 freeze/collect/unfreeze 状态机同步产出：DXGI Desktop Duplication 抓 RGB、HLSL 着色器加 FNV-1a 纹理哈希做实例分割、INTZ 深度纹理拿逐像素深度、从动画系统直接读 18 关节骨骼（无估计器在回路中，故无抖动且遮挡标签精确）、逐帧全实体成对空间关系（一帧 32 个实体即 496 条关系）、2D 包围盒、事件-帧区间映射与自然语言描述。生成侧的失败经验很有价值：最初的六阶段提示精化流水线在 <strong>50 次尝试中零次</strong>产出可执行规格，失败模式包括幻觉动作、非法动作链、物体生命周期违规、解不开的时序环；教训是<strong>LLM 只做叙事决策，程序化后端负责状态与约束</strong>，最终架构是 Director 加 Scene Builder 全程走被状态后端校验的 function call。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>时序编排是全文的形式化核心。给定事件集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span></span></span></span> 与约束集 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0583em;">C</span></span></span></span>，先建 happens-before 图 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0813em;">H</span></span></span></span>：<code>before</code> 加一条 source 到 target 的边，<code>after</code> 反向，<code>same_time</code> 推出传递边。随后用 Floyd–Warshall 求传递闭包 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6887em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∗</span></span></span></span></span></span></span></span></span></span></span></span>：对任意三元组 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">i</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mclose">)</span></span></span></span>，若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6986em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≺</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 且 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≺</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span> 则 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6986em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">i</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">≺</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.854em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span></span></span></span>。直觉是把显式写下的局部约束补全成全部隐含的全局约束——Alice 吃完饭 Bob 才能打电话、Bob 打完 Carol 才能离开，那么 Alice 吃饭就隐式约束了 Carol 离开。这步必要，因为调度器必须看到间接依赖才能判断事件是否就绪。</p><p>闭包后分段：每轮取</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">ready</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord mathnormal">e</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0822em;">V</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">∖</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord text"><span class="mord">satisfied</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∣</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">IsReady</span></span><span class="mopen">(</span><span class="mord mathnormal">e</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∗</span></span></span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord text"><span class="mord">satisfied</span></span><span class="mclose">)}</span></span></span></span></span></p><p><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathrm" style="margin-right:0.0139em;">IsReady</span></span></span></span></span> 同时检查同角色前驱已完成、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6887em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0813em;">H</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6887em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">∗</span></span></span></span></span></span></span></span></span></span></span></span> 中所有前置已完成、<code>same_time</code> 伙伴也就绪；就绪事件按并发兼容性分组成段，段内并发段间串行，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord text"><span class="mord">ready</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6633em;vertical-align:-0.0817em;"></span><span class="mord amsrm">∅</span></span></span></span> 而仍有未分配事件即报告循环依赖。episode 选择是加权 set-cover 变体，作者诚实指出算法<strong>可靠但不最优</strong>：能找到可行解不保证最小，但候选只有 11 个，贪心已接近最小覆盖。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>必须明确指出：<strong>这份技术报告本身不含定量实验</strong>，作者反复把评测指向一份 companion evaluation，本文只描述系统。可读出的定量事实主要在工程侧：当前 11 个 episode、6 类环境、124 个模板用于视觉多样性；语料的故事含 2–6 角色、7–65 事件、1–4 区域，最复杂的图有 6 角色、4 地点、50+ 事件、30 条时序约束；生产系统在单台工作站跑 25 个并行 VM，选 2004 年的游戏正因它不需独显。文本侧选中 GPT-4o，因为 GPT-5 系列倾向过度概括、把多个动作压成逗号列表从而破坏与视频对应的顺序叙事。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：GEST-Engine 把事件的时空图当作可执行规格，在 GTA:San Andreas 上确定性演出。四阶段流水线负责场景选择、实体接地、Floyd–Warshall 时序编排与执行采集。一次仿真同步产出 RGB、深度、纹理级实例分割、18 关节骨骼、逐帧成对空间关系、事件-帧映射与自然语言描述，标注边际成本为零。因为每帧都能回溯到语义规格，物体恒存、多角色协同、时序一致是构造性保证。agentic 生成的关键教训是让 LLM 只做叙事决策、把状态与合法性交给程序化后端，否则 50 次尝试零次可执行。</p><p><strong>3 句话版</strong>：用形式化事件图驱动商业游戏引擎，把视频生成变成规格编译而非分布采样。全部密集标注是单次仿真的副产品且与规格一一对应。LLM 通过被校验的 function call 写图，从而构造上可执行。</p><p><strong>1 句话版</strong>：显式世界模型版的视频生成——先写规格再演出来，标注免费。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱且代价最大的假设是：<strong>语义正确的合成视频对下游真实任务有用</strong>。训练数据、评测 benchmark、诊断工具三项价值主张全建立在它之上。</p><p>它可能不成立的原因很具体：渲染器是 2004 年的引擎；分割是纹理级而非物体级（扶手椅的木腿与织物座面成为两个 segment），且动态光影本身被当作半透明纹理参与哈希、会覆盖底层物体纹理，作者承认这在户外尤其严重且<strong>如何缓解仍是未解决的工程问题</strong>；深度是后投影非线性值，远平面外精度崩塌。</p><p>论文的证据是<strong>间接的</strong>：引用 BEDLAM 证明纯合成数据可在真实姿态 benchmark 达到 SOTA，以及 Richter 等人证明合成加真实优于纯真实。但 BEDLAM 用 Unreal 做照片级渲染且只针对姿态这一个几何量，Richter 只做语义分割，外推到「叙事级多角色视频理解」缺一个中间环节。而本报告把全部下游验证推给了 companion evaluation，因此在这份文档内部，这条最关键的假设是<strong>零直接证据</strong>的。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要重建引擎。从公开的 VirtualHome 或 AI2-THOR 取一小批带动作标签的合成视频（作为「弱真实感 + 强标注」替身），另取同量级真实视频片段；训练同一个小型视频编码器做二分类探针——给定一段视频与两个事件 ID，判断 A 是否早于 B，合成侧标签直接来自事件-帧映射；设纯合成、纯真实、合成预训练加真实微调三组，真实测试集固定；测量准确率随真实数据量的曲线。<strong>判定标准</strong>：若合成预训练组显著高于纯真实组，则合成时序监督确实迁移；若三条曲线收敛到同一水平，说明合成数据只省了标注钱；若纯合成组接近随机，则视觉域差距已吃掉全部语义优势。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击是指出一类<strong>可预测的系统性失败</strong>：GEST 的动作词表来自人工在 World Editor 里标注的 POI 动作链，因此整个语料的事件分布被人为模板集合完全决定，124 个模板、46 个动作、11 个场景意味着动作共现的联合分布<strong>低秩且封闭</strong>。实验：用该语料训练动作序列预测器，在「人为违反常见共现模式的图」（如 <code>StandUp</code> 后直接 <code>Sleep</code>）与真实视频两个测试集上评；若前者大幅退化，说明模型拟合的是模板统计而非物理约束——而这些约束恰恰被引擎在构造时替它满足掉了，模型因此<strong>从未被迫学会</strong>它们。这给出了对论文结论的替代解释：构造性保证在提供干净标签的同时，也移除了学习这些规律所需的反例。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：系统产出的是「正确的世界」，但视频理解模型真正缺的训练信号往往是「<strong>几乎正确但某处违反了物理或因果的世界</strong>」，而构造性保证让引擎在结构上无法生产反例。</p><p><strong>新 framing</strong>：把 GEST-Engine 从数据生成器重定位为<strong>反事实生成器</strong>——它的独特优势不是能演对，而是能对同一份规格做最小语义扰动后再演一遍，产出严格配对的正负样本；可借鉴软件测试的变异测试与因果推断的干预算子，定义一组语义变异算子（反转一条 <code>before</code> 边、把 <code>same_time</code> 拆成串行、删掉动作链中间一步），每个变异只改一处、其余渲染条件全部锁死。</p><p><strong>第一个实验</strong>：取 200 个 GEST 各生成 1 正 4 负共 1,000 段配对视频，训练一个时序/因果一致性判别器，再拿它去评价 Sora、VEO 3、Wan 的输出并与人工判断做相关性分析。核心观测量是判别器在真实视频上的假阳率及其与人工打分的 Spearman 相关。若相关性显著，就得到一个<strong>由构造性规格支撑的可扩展视频物理一致性自动评测器</strong>，且正好绕开 §9 那条未被验证的 sim-to-real 假设——判别器只需区分同一渲染域内的正负对。</p>',39)])])}const d=a(r,[["render",p]]);export{g as __pageData,d as default};
